import React, { ChangeEvent, PropsWithChildren, useId } from "react";
import Stack from "../Stack";
import Inline, { InlineProps } from "../Inline";
import useControlled from "../../lib/hooks/useControlled";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /** The default value for an uncontrolled group */
  defaultValue?: any;
  /** The name of the group */
  name?: string;
  /** The callback for when the input checked status changes */
  onChange?: (event: ChangeEvent<HTMLInputElement>, value: any) => void;
  /** Customise the props passed to the root Inline component */
  rootProps?: InlineProps;
  /** If `true`, radios will be shown in a row */
  row?: boolean;
  /** Current value when [controlled](https://react.dev/learn/sharing-state-between-components#controlled-and-uncontrolled-components)  */
  value?: any;
}>;

export type RadioGroupProps = Props & CommonProps;

const RadioGroup = ({
  children,
  className,
  defaultValue = [],
  name: nameProp,
  onChange,
  rootProps,
  row,
  style,
  value: valueProp,
  ...rest
}: RadioGroupProps) => {
  const defaultName = `radiogroup-${useId()}`;
  const name = nameProp || defaultName;
  const [value, setValueState] = useControlled({
    value: valueProp,
    defaultValue,
  });

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => {
    setValueState(e.target.value);
    if (onChange) {
      onChange(e, e.target.value);
    }
  };

  let Component = row ? Inline : Stack;
  // FIXME Inline and Stack have a conflicting prop type for align prop
  const componentProps: any = { className, style, ...rest, ...rootProps };

  return (
    <Component
      role="radiogroup"
      spacing="1-x"
      wrapChildren={true}
      {...componentProps}
    >
      {React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) {
          return null;
        }
        if (process.env.NODE_ENV !== "production") {
          if (child.type === React.Fragment) {
            console.warn(
              "The RadioGroup component doesn't accept a Fragment as a child. Consider providing an array instead."
            );
          }
        }

        const childProps = child.props as any;
        return React.cloneElement<any>(child, {
          name,
          checked:
            value === childProps.value || value === childProps.value.toString(),
          onChange: handleChange,
        });
      })}
    </Component>
  );
};

export default RadioGroup;
